import Foundation

/// SVT-AV1 v4.2.0, the `av1` row's encoder (spec §11 CX-2, CX-4, CX-12): one handle per
/// export, configured once, fed BT.709 video-range I420 pictures and drained of packets.
///
/// **Owned by one serial queue.** `ExportEncodePump`'s encode queue makes every call after
/// `init` — `send`, `sendEndOfStream`, `nextPacket` and the `deinit` — so the handle is
/// never touched from two threads; SVT runs its own worker threads behind it.
///
/// **The configuration** (CX-12 (2), (3); CX-13): the sheet's speed as SVT's preset (8, 6 or
/// 4), capped CRF — a constant quality matched to HEVC's at the cap, which is the settings'
/// rate or HEVC's 0.07 bits per pixel per frame — a closed GOP (`SVT_AV1_KF_REFRESH`) with a
/// keyframe at least every 2 s, 8-bit 4:2:0, and BT.709 primaries, transfer and matrix in
/// video range written into the sequence header.
final class SVTAV1Encoder {
    /// One packet as SVT answered it: its bytes (temporal delimiters still in), the `pts` the
    /// picture was sent with, and whether it is the last.
    struct Packet {
        let data: Data
        let pts: Int64
        let isLast: Bool
    }

    /// The sequence header OBU (`svt_av1_enc_stream_header`), the `av1C` record's source.
    let sequenceHeader: Data

    private var handle: UnsafeMutablePointer<EbComponentType>?
    /// Set after the first failed call: nothing more is asked of the handle but its teardown.
    private var broken = false

    init(width: Int, height: Int, fps: Fps, bitsPerSecond: Int, speed: EncoderSpeed) throws {
        _ = Self.installLogCallback
        var config = EbSvtAv1EncConfiguration()
        var opened: UnsafeMutablePointer<EbComponentType>?
        try Self.check(svt_av1_enc_init_handle(&opened, &config), "svt_av1_enc_init_handle")
        guard let opened else {
            throw Exporter.ExportError.failed("SVT-AV1 could not start: no handle was made.")
        }
        config.enc_mode = speed.svtPreset
        config.source_width = UInt32(clamping: width)
        config.source_height = UInt32(clamping: height)
        config.frame_rate_numerator = UInt32(clamping: fps.num)
        config.frame_rate_denominator = UInt32(clamping: fps.den)
        config.encoder_bit_depth = 8
        config.encoder_color_format = EB_YUV420
        // Capped CRF (CX-13): what SVT's own `--crf` sets, and the cap as `max_bit_rate`.
        let cap = min(max(1, bitsPerSecond), Self.maxCap)
        config.rate_control_mode = UInt8(SVT_AV1_RC_MODE_CQP_OR_CRF.rawValue)
        config.aq_mode = 2
        config.qp = Self.crf(speed: speed, bitsPerPixel: Double(cap)
            / (Double(max(1, width * height)) * (fps.double > 0 ? fps.double : 30)))
        config.max_bit_rate = UInt32(cap)
        // SVT-AV1 v4.2.0's own default (`EbSvtAv1Enc.h`, `enc_settings.c`): a soft cap that
        // hard footage may exceed, the owner's "quality first" (CX-13 (1)).
        config.mbr_over_shoot_pct = 50
        // Closed GOP, and a keyframe at least every 2 s: the period is ⌊2·fps⌋ frames.
        config.intra_refresh_type = SVT_AV1_KF_REFRESH
        let perSecond = fps.den > 0 ? Double(fps.num) / Double(fps.den) : 30
        config.intra_period_length = Int32(max(1, (2 * perSecond).rounded(.down))) - 1
        config.color_primaries = EB_CICP_CP_BT_709
        config.transfer_characteristics = EB_CICP_TC_BT_709
        config.matrix_coefficients = EB_CICP_MC_BT_709
        config.color_range = EB_CR_STUDIO_RANGE
        do {
            sequenceHeader = try Self.start(opened, &config)
        } catch {
            _ = svt_av1_enc_deinit(opened)
            _ = svt_av1_enc_deinit_handle(opened)
            throw error
        }
        handle = opened
    }

    /// Configures and starts the handle, answering its sequence header.
    private static func start(
        _ handle: UnsafeMutablePointer<EbComponentType>, _ config: inout EbSvtAv1EncConfiguration
    ) throws -> Data {
        try check(svt_av1_enc_set_parameter(handle, &config), "svt_av1_enc_set_parameter")
        try check(svt_av1_enc_init(handle), "svt_av1_enc_init")
        var header: UnsafeMutablePointer<EbBufferHeaderType>?
        try check(svt_av1_enc_stream_header(handle, &header), "svt_av1_enc_stream_header")
        guard let header, let bytes = header.pointee.p_buffer else {
            throw Exporter.ExportError.failed("SVT-AV1 could not start: it wrote no stream header.")
        }
        defer { _ = svt_av1_enc_stream_header_release(header) }
        return Data(bytes: bytes, count: Int(header.pointee.n_filled_len))
    }

    @available(*, unavailable) required init?(coder: NSCoder) {
        fatalError("SVTAV1Encoder does not support NSCoder")
    }

    deinit {
        guard let handle else { return }
        _ = svt_av1_enc_deinit(handle)
        _ = svt_av1_enc_deinit_handle(handle)
    }

    /// Sends one picture; SVT copies its planes, so `frame` may be reused once this returns.
    func send(_ frame: I420Frame, index: Int64) throws {
        guard let handle, !broken else { throw Self.stopped }
        let base = frame.buffer.contents().assumingMemoryBound(to: UInt8.self)
        var planes = EbSvtIOFormat(
            luma: base, cb: base + frame.cbOffset, cr: base + frame.crOffset,
            y_stride: UInt32(frame.lumaStride), cr_stride: UInt32(frame.chromaStride),
            cb_stride: UInt32(frame.chromaStride))
        try withUnsafeMutablePointer(to: &planes) { io in
            var picture = EbBufferHeaderType()
            picture.size = UInt32(MemoryLayout<EbBufferHeaderType>.size)
            picture.p_buffer = UnsafeMutableRawPointer(io).assumingMemoryBound(to: UInt8.self)
            let chroma = frame.chromaStride * ((frame.height + 1) / 2)
            picture.n_filled_len = UInt32(frame.lumaStride * frame.height + 2 * chroma)
            picture.n_alloc_len = picture.n_filled_len
            picture.pts = index
            picture.pic_type = EB_AV1_INVALID_PICTURE
            try record(svt_av1_enc_send_picture(handle, &picture), "svt_av1_enc_send_picture")
        }
    }

    /// Tells SVT no picture follows, so `nextPacket(wait: true)` drains to the last packet.
    func sendEndOfStream() throws {
        guard let handle, !broken else { throw Self.stopped }
        var end = EbBufferHeaderType()
        end.size = UInt32(MemoryLayout<EbBufferHeaderType>.size)
        end.flags = UInt32(EB_BUFFERFLAG_EOS)
        end.pic_type = EB_AV1_INVALID_PICTURE
        try record(svt_av1_enc_send_picture(handle, &end), "svt_av1_enc_send_picture")
    }

    /// The next packet: nil when none is ready (`wait` false); `wait` true blocks until one
    /// is, which is only asked after `sendEndOfStream`.
    func nextPacket(wait: Bool) throws -> Packet? {
        guard let handle, !broken else { throw Self.stopped }
        var out: UnsafeMutablePointer<EbBufferHeaderType>?
        let answer = svt_av1_enc_get_packet(handle, &out, wait ? 1 : 0)
        if answer == EB_NoErrorEmptyQueue { return nil }
        try record(answer, "svt_av1_enc_get_packet")
        guard let header = out?.pointee else { return nil }
        defer { svt_av1_enc_release_out_buffer(&out) }
        let length = Int(header.n_filled_len)
        let data = header.p_buffer.map { Data(bytes: $0, count: length) } ?? Data()
        return Packet(
            data: data, pts: header.pts, isLast: header.flags & UInt32(EB_BUFFERFLAG_EOS) != 0)
    }

    // MARK: - The rate (CX-13)

    /// SVT-AV1's largest `max_bit_rate`, 100,000 kb/s.
    private static let maxCap = 100_000_000

    /// CX-13 (3)'s calibration: at each cap in bits per pixel per frame (the Quality tiers'
    /// and "Format default"'s at 1080p30), the highest CRF at which each speed reached VMAF
    /// ≥ HEVC's at that rate on every calibration clip — the spike's three 8-bit clips and
    /// the owner's 55 s clip through this app — Faster, Balanced, Smaller file.
    private static let calibration: [(bitsPerPixel: Double, crf: [EncoderSpeed: Double])] = [
        (0.0386, [.faster: 40, .balanced: 36, .smaller: 36]),
        (0.0579, [.faster: 28, .balanced: 30, .smaller: 30]),
        (0.0700, [.faster: 24, .balanced: 26, .smaller: 26]),
        (0.0772, [.faster: 22, .balanced: 24, .smaller: 24]),
        (0.1157, [.faster: 14, .balanced: 16, .smaller: 16]),
    ]

    /// The CRF for `speed` at a cap of `bitsPerPixel`: linear between the calibrated points,
    /// rounded down, and the end point's beyond either end.
    static func crf(speed: EncoderSpeed, bitsPerPixel: Double) -> UInt32 {
        let points = calibration.map { ($0.bitsPerPixel, $0.crf[speed] ?? 32) }
        guard let first = points.first, let last = points.last else { return 32 }
        if !(bitsPerPixel > first.0) { return UInt32(first.1) }
        if bitsPerPixel >= last.0 { return UInt32(last.1) }
        for (low, high) in zip(points, points.dropFirst()) where bitsPerPixel < high.0 {
            let share = (bitsPerPixel - low.0) / (high.0 - low.0)
            return UInt32((low.1 + share * (high.1 - low.1)).rounded(.down))
        }
        return UInt32(last.1)
    }

    // MARK: - Errors and the log

    private static let stopped = Exporter.ExportError.failed(
        "SVT-AV1 stopped after an earlier error.")

    private func record(_ answer: EbErrorType, _ step: String) throws {
        guard answer != EB_ErrorNone else { return }
        broken = true
        throw Exporter.ExportError.failed("SVT-AV1 failed: \(step) answered \(Self.hex(answer)).")
    }

    private static func check(_ answer: EbErrorType, _ step: String) throws {
        guard answer != EB_ErrorNone else { return }
        throw Exporter.ExportError.failed(
            "SVT-AV1 could not start: \(step) answered \(hex(answer)).")
    }

    private static func hex(_ answer: EbErrorType) -> String {
        "0x" + String(UInt32(bitPattern: answer.rawValue), radix: 16)
    }

    /// SVT's log through its callback (spec §11 CX-12 (6)), installed once per process before
    /// the first `svt_av1_enc_init_handle`, which finalises the library's logging: info and
    /// debug dropped, warnings and errors as `SVT-AV1: …` lines in the system log.
    private static let installLogCallback: Void = {
        svt_av1_set_log_callback({ _, level, _, format, arguments in
            guard level.rawValue >= 0, level.rawValue <= SVT_AV1_LOG_WARN.rawValue, let format,
                let arguments
            else { return }
            var text = [CChar](repeating: 0, count: 1024)
            _ = vsnprintf(&text, text.count, format, arguments)
            let line = String(cString: text).trimmingCharacters(in: .whitespacesAndNewlines)
            NSLog("SVT-AV1: %@", line)
        }, nil)
    }()
}
import CoreVideo
import Metal
import MetalPerformanceShaders

/// One picture for SVT-AV1: 8-bit planar 4:2:0 in one shared buffer — luma, then Cb at
/// `cbOffset`, then Cr at `crOffset`, each row `lumaStride` or `chromaStride` bytes.
struct I420Frame {
    let buffer: MTLBuffer
    let width: Int
    let height: Int
    let lumaStride: Int
    let chromaStride: Int
    let cbOffset: Int
    let crOffset: Int
}

/// `ExportI420.metal`'s uniforms, field for field.
private struct ExportI420Uniforms {
    var width: UInt32
    var height: UInt32
    var lumaStride: UInt32
    var chromaStride: UInt32
    var cbOffset: UInt32
    var crOffset: UInt32
}

/// The compositor's 64RGBAHalf frames as BT.709 video-range I420 for the `av1` row (spec
/// §11 CX-12 (5)), on the GPU: `MPSImageLanczosScale` to the export size when it is not the
/// canvas — the picture fitted inside with black bars, or filling a frame within a pixel of
/// the canvas's shape (`fills`, G-33 (c)) — then `framejob_export_i420`.
///
/// Called on the export's video queue alone; the planes come from a pool the encode queue
/// gives back through `recycle` once SVT has copied them.
final class ExportI420Converter {
    let width: Int
    let height: Int

    private let device: MTLDevice
    private let queue: MTLCommandQueue
    private let pipeline: MTLComputePipelineState
    private let cache: CVMetalTextureCache
    /// The scaler, its transform and clip, and the export-size texture it writes; nil when
    /// the export is at the canvas size.
    private let scaler: MPSImageLanczosScale?
    private let scaled: MTLTexture?
    private var transform = MPSScaleTransform(scaleX: 1, scaleY: 1, translateX: 0, translateY: 0)
    private let lumaStride: Int
    private let chromaStride: Int
    private let length: Int

    private let lock = NSLock()
    private var pool: [I420Frame] = []

    init(width: Int, height: Int, canvas: CGSize, fills: Bool, pool count: Int) throws {
        func failure(_ what: String) -> Exporter.ExportError {
            .failed("The frames could not be prepared for the AV1 encoder: \(what).")
        }
        guard let device = MTLCreateSystemDefaultDevice(), let queue = device.makeCommandQueue()
        else { throw failure("no Metal device") }
        guard let library = (try? device.makeDefaultLibrary(bundle: Bundle.main))
            ?? device.makeDefaultLibrary(),
            let function = library.makeFunction(name: "framejob_export_i420"),
            let pipeline = try? device.makeComputePipelineState(function: function)
        else { throw failure("the conversion kernel is missing") }
        var cache: CVMetalTextureCache?
        guard CVMetalTextureCacheCreate(kCFAllocatorDefault, nil, device, nil, &cache)
            == kCVReturnSuccess, let cache
        else { throw failure("no texture cache") }
        self.width = width
        self.height = height
        self.device = device
        self.queue = queue
        self.pipeline = pipeline
        self.cache = cache
        lumaStride = width
        chromaStride = (width + 1) / 2
        length = lumaStride * height + 2 * chromaStride * ((height + 1) / 2)

        let canvasWidth = Int(canvas.width.rounded())
        let canvasHeight = Int(canvas.height.rounded())
        if canvasWidth == width && canvasHeight == height || canvasWidth < 1 || canvasHeight < 1 {
            scaler = nil
            scaled = nil
        } else {
            let made = try Self.scaling(
                device: device, size: (width, height), canvas: canvas, fills: fills)
            scaler = made.scaler
            scaled = made.texture
            transform = made.transform
        }
        for _ in 0..<max(1, count) {
            pool.append(try makeFrame())
        }
    }

    @available(*, unavailable) required init?(coder: NSCoder) {
        fatalError("ExportI420Converter does not support NSCoder")
    }

    /// The Lanczos scaler, its transform and clip, and a destination cleared to black once:
    /// a fit writes only the picture's rectangle, so the bars stay black on every frame.
    private static func scaling(
        device: MTLDevice, size: (Int, Int), canvas: CGSize, fills: Bool
    ) throws -> (scaler: MPSImageLanczosScale, texture: MTLTexture, transform: MPSScaleTransform) {
        let (w, h) = (Double(size.0), Double(size.1))
        let (cw, ch) = (Double(canvas.width), Double(canvas.height))
        let s = fills ? max(w / cw, h / ch) : min(w / cw, h / ch)
        let (pw, ph) = (cw * s, ch * s)
        let transform = MPSScaleTransform(
            scaleX: s, scaleY: s, translateX: (w - pw) / 2, translateY: (h - ph) / 2)
        let descriptor = MTLTextureDescriptor.texture2DDescriptor(
            pixelFormat: .rgba16Float, width: size.0, height: size.1, mipmapped: false)
        descriptor.usage = [.shaderRead, .shaderWrite]
        descriptor.storageMode = .shared
        guard let texture = device.makeTexture(descriptor: descriptor) else {
            throw Exporter.ExportError.failed(
                "The frames could not be prepared for the AV1 encoder: no scaling texture.")
        }
        let zeros = [UInt16](repeating: 0, count: size.0 * size.1 * 4)
        texture.replace(
            region: MTLRegionMake2D(0, 0, size.0, size.1), mipmapLevel: 0, withBytes: zeros,
            bytesPerRow: size.0 * 8)
        let scaler = MPSImageLanczosScale(device: device)
        if !fills {
            let x = max(0, Int(((w - pw) / 2).rounded()))
            let y = max(0, Int(((h - ph) / 2).rounded()))
            scaler.clipRect = MTLRegionMake2D(
                x, y, min(size.0 - x, Int(pw.rounded())), min(size.1 - y, Int(ph.rounded())))
        }
        return (scaler, texture, transform)
    }

    private func makeFrame() throws -> I420Frame {
        guard let buffer = device.makeBuffer(length: length, options: .storageModeShared) else {
            throw Exporter.ExportError.failed(
                "The frames could not be prepared for the AV1 encoder: no plane buffer.")
        }
        let chromaBytes = chromaStride * ((height + 1) / 2)
        return I420Frame(
            buffer: buffer, width: width, height: height, lumaStride: lumaStride,
            chromaStride: chromaStride, cbOffset: lumaStride * height,
            crOffset: lumaStride * height + chromaBytes)
    }

    /// One frame converted, waiting for the GPU; nil when it could not be wrapped or the
    /// GPU failed.
    func convert(_ frame: CVPixelBuffer) -> I420Frame? {
        guard let source = wrap(frame), let texture = CVMetalTextureGetTexture(source),
            let out = take(), let commands = queue.makeCommandBuffer()
        else { return nil }
        var input = texture
        if let scaler, let scaled {
            withUnsafePointer(to: &transform) { pointer in
                scaler.scaleTransform = pointer
                scaler.encode(
                    commandBuffer: commands, sourceTexture: texture, destinationTexture: scaled)
                scaler.scaleTransform = nil
            }
            input = scaled
        }
        guard let encoder = commands.makeComputeCommandEncoder() else {
            recycle(out)
            return nil
        }
        var uniforms = ExportI420Uniforms(
            width: UInt32(width), height: UInt32(height), lumaStride: UInt32(lumaStride),
            chromaStride: UInt32(chromaStride), cbOffset: UInt32(out.cbOffset),
            crOffset: UInt32(out.crOffset))
        encoder.setComputePipelineState(pipeline)
        encoder.setTexture(input, index: 0)
        encoder.setBuffer(out.buffer, offset: 0, index: 0)
        encoder.setBytes(&uniforms, length: MemoryLayout<ExportI420Uniforms>.stride, index: 1)
        let group = MTLSize(width: 16, height: 16, depth: 1)
        let blocks = MTLSize(width: (width + 1) / 2, height: (height + 1) / 2, depth: 1)
        encoder.dispatchThreads(blocks, threadsPerThreadgroup: group)
        encoder.endEncoding()
        commands.commit()
        commands.waitUntilCompleted()
        withExtendedLifetime(source) {}
        guard commands.status == .completed else {
            recycle(out)
            return nil
        }
        return out
    }

    /// Gives a frame's planes back to the pool.
    func recycle(_ frame: I420Frame) {
        lock.lock()
        pool.append(frame)
        lock.unlock()
    }

    private func take() -> I420Frame? {
        lock.lock()
        let frame = pool.popLast()
        lock.unlock()
        return frame ?? (try? makeFrame())
    }

    /// The frame as a Metal texture over the same IOSurface.
    private func wrap(_ frame: CVPixelBuffer) -> CVMetalTexture? {
        CVMetalTextureCacheFlush(cache, 0)
        var wrapper: CVMetalTexture?
        let status = CVMetalTextureCacheCreateTextureFromImage(
            kCFAllocatorDefault, cache, frame, nil, .rgba16Float,
            CVPixelBufferGetWidth(frame), CVPixelBufferGetHeight(frame), 0, &wrapper)
        return status == kCVReturnSuccess ? wrapper : nil
    }
}
//
//  ExportI420.metal — the `av1` row's frames for SVT-AV1 (spec §11 CX-12 (5)):
//  a compositor frame (64RGBAHalf, SDR BT.709, premultiplied) converted to
//  BT.709 video-range 8-bit I420 in three planes of one buffer. Owned by
//  `app/Sources/ExportI420.swift`, which scales the frame to the export size
//  first when it is not the canvas.
//
//  One thread per 2 × 2 block: it writes the block's four luma samples and
//  one Cb and one Cr, the mean of the four pixels' (a 2 × 2 box, the chroma
//  siting SVT's sequence header leaves unspecified). RGB is clamped to 0…1 and
//  read as it is, premultiplied, so a transparent canvas lands on black as it
//  does through VideoToolbox on `h264`.
//
//  Y′ = 0.2126 R + 0.7152 G + 0.0722 B; Y = round(16 + 219 Y′);
//  Cb = round(128 + 224 (B − Y′) / 1.8556); Cr = round(128 + 224 (R − Y′) / 1.5748).
//

#include <metal_stdlib>
using namespace metal;

/// Mirrored by `ExportI420Uniforms` in `ExportI420.swift`; every field 32 bits.
struct ExportI420Uniforms {
    uint width;
    uint height;
    uint lumaStride;
    uint chromaStride;
    uint cbOffset;
    uint crOffset;
};

kernel void framejob_export_i420(texture2d<half, access::read> src [[texture(0)]],
                                 device uchar *planes [[buffer(0)]],
                                 constant ExportI420Uniforms &u [[buffer(1)]],
                                 uint2 gid [[thread_position_in_grid]]) {
    if (gid.x * 2 >= u.width || gid.y * 2 >= u.height) {
        return;
    }
    const float3 weights = float3(0.2126, 0.7152, 0.0722);
    float cb = 0.0;
    float cr = 0.0;
    float count = 0.0;
    for (uint dy = 0; dy < 2; dy++) {
        for (uint dx = 0; dx < 2; dx++) {
            uint2 at = uint2(gid.x * 2 + dx, gid.y * 2 + dy);
            if (at.x >= u.width || at.y >= u.height) {
                continue;
            }
            float3 rgb = clamp(float3(src.read(at).rgb), 0.0, 1.0);
            float luma = dot(rgb, weights);
            planes[at.y * u.lumaStride + at.x] = uchar(round(16.0 + 219.0 * luma));
            cb += (rgb.b - luma) / 1.8556;
            cr += (rgb.r - luma) / 1.5748;
            count += 1.0;
        }
    }
    uint chroma = gid.y * u.chromaStride + gid.x;
    planes[u.cbOffset + chroma] = uchar(clamp(round(128.0 + 224.0 * cb / count), 0.0, 255.0));
    planes[u.crOffset + chroma] = uchar(clamp(round(128.0 + 224.0 * cr / count), 0.0, 255.0));
}

